import fs from 'fs';
import os from 'os';
import path from 'path';
import {
  AgentVariantsOrchestrator,
  type PreviewQaRunner,
  type ProjectEnvironment,
  type WorktreeManagerLike,
} from './WorktreeOrchestrator';
import { SessionStore } from './SessionStore';
import type { WorktreeCreationOptions } from './variant-project-runtime';
import type { Brief, DesignContextEntry, VariantQaResult } from './contracts';

export interface RecordedCall {
  method: string;
  args: unknown[];
}

export class FakeWorktreeManager implements WorktreeManagerLike {
  calls: RecordedCall[] = [];
  diffByPath: Record<string, string> = {};
  getDiffImpl: ((worktreePath: string) => Promise<string>) | undefined;
  freePortSeq = 5170;
  startDevServerImpl: () => Promise<unknown> = async () => ({
    once: () => undefined,
  });

  createWorktreesImpl:
    | ((
        sessionId: string,
        count: number,
        instanceKeyPrefix?: string,
      ) => Promise<string[]>)
    | undefined;
  forkWorktreesFromImpl:
    | ((
        sourceWorktreePath: string,
        sessionId: string,
        count: number,
        instanceKeyPrefix?: string,
      ) => Promise<string[]>)
    | undefined;

  async createWorktrees(
    sessionId: string,
    count: number,
    instanceKeyPrefix = '',
    options: WorktreeCreationOptions = {},
  ): Promise<string[]> {
    this.calls.push({
      method: 'createWorktrees',
      args: [sessionId, count, instanceKeyPrefix, options],
    });
    if (this.createWorktreesImpl) {
      return this.createWorktreesImpl(sessionId, count, instanceKeyPrefix);
    }
    return Array.from(
      { length: count },
      (_, i) => `/tmp/wt-${sessionId.slice(0, 8)}-${instanceKeyPrefix}${i}`,
    );
  }

  async forkWorktreesFrom(
    sourceWorktreePath: string,
    sessionId: string,
    count: number,
    instanceKeyPrefix = '',
  ): Promise<string[]> {
    this.calls.push({
      method: 'forkWorktreesFrom',
      args: [sourceWorktreePath, sessionId, count, instanceKeyPrefix],
    });
    if (this.forkWorktreesFromImpl) {
      return this.forkWorktreesFromImpl(
        sourceWorktreePath,
        sessionId,
        count,
        instanceKeyPrefix,
      );
    }
    return Array.from({ length: count }, (_, i) => {
      const dir = fs.mkdtempSync(
        path.join(os.tmpdir(), `wt-fork-${sessionId.slice(0, 8)}-${i}-`),
      );
      if (fs.existsSync(sourceWorktreePath)) {
        fs.cpSync(sourceWorktreePath, dir, { recursive: true });
      }
      return dir;
    });
  }

  freshWorktreePathFactory: (sessionId: string, i: number) => string = (
    sessionId,
    i,
  ) => `/tmp/wt-${sessionId.slice(0, 8)}-${i}`;

  async createFreshWorktrees(
    sessionId: string,
    count: number,
    _template: unknown,
    designContext: ReadonlyArray<DesignContextEntry | undefined> | undefined,
    destinationParent: string,
  ): Promise<string[]> {
    this.calls.push({
      method: 'createFreshWorktrees',
      args: [sessionId, count, designContext ?? null, destinationParent],
    });
    return Array.from({ length: count }, (_, i) =>
      this.freshWorktreePathFactory(sessionId, i),
    );
  }

  async getDiff(worktreePath: string): Promise<string> {
    this.calls.push({ method: 'getDiff', args: [worktreePath] });
    if (this.getDiffImpl) {
      return this.getDiffImpl(worktreePath);
    }
    return (
      this.diffByPath[worktreePath] ??
      `diff --git a/file.tsx b/file.tsx\n--- a/file.tsx\n+++ b/file.tsx\n@@ -1 +1 @@\n-old\n+new\n`
    );
  }

  async cleanupSession(
    sessionId: string,
    freshDestinationParent?: string,
  ): Promise<void> {
    this.calls.push({
      method: 'cleanupSession',
      args: [sessionId, freshDestinationParent],
    });
  }

  async getFreePort(): Promise<number> {
    const port = this.freePortSeq;
    this.freePortSeq += 1;
    this.calls.push({ method: 'getFreePort', args: [] });
    return port;
  }

  async findFreePortFrom(startPort: number): Promise<number> {
    this.calls.push({ method: 'findFreePortFrom', args: [startPort] });
    return startPort;
  }

  async startDevServer(
    worktreePath: string,
    port: number,
    cmd: string,
    args: string[],
    env: Record<string, string>,
  ) {
    this.calls.push({
      method: 'startDevServer',
      args: [worktreePath, port, cmd, args, env],
    });
    return (await this.startDevServerImpl()) as never;
  }

  async stopDevServer() {
    this.calls.push({ method: 'stopDevServer', args: [] });
  }

  async getProjectCwdInWorktree(worktreePath: string): Promise<string> {
    this.calls.push({
      method: 'getProjectCwdInWorktree',
      args: [worktreePath],
    });
    return worktreePath;
  }
}

export const ENV: ProjectEnvironment = {
  projectPath: '/repo',
  framework: 'vite',
  packageManager: 'yarn',
  devCommand: 'dev',
};

export interface OrchestratorHarness {
  installCalls: Array<{ worktreePath: string }>;
  installResult: Promise<void>;
  destinationExists: boolean;
  telemetryEvents: Array<{
    event: string;
    properties?: Record<string, unknown>;
  }>;
  switchPreviewPortCalls: Array<number | null>;
}

export const PASSING_QA: VariantQaResult = {
  status: 'passed',
  issues: [],
  summary: 'Preview QA passed (test default).',
};

export const passingQaRunner: PreviewQaRunner = async () => PASSING_QA;

export function buildOrchestrator(
  opts: {
    destinationExists?: boolean;
    previewQaRunner?: PreviewQaRunner;
    provisionTimeoutMs?: number;
    activeVariantServerIdleTtlMs?: number;
    devServerRestartDelayMs?: number;
    env?: ProjectEnvironment;
    resolveProjectEnvironment?: () => Promise<ProjectEnvironment>;
  } = {},
) {
  const store = new SessionStore();
  const worktreeManager = new FakeWorktreeManager();
  const harness: OrchestratorHarness = {
    installCalls: [],
    installResult: Promise.resolve(),
    destinationExists: opts.destinationExists ?? false,
    telemetryEvents: [],
    switchPreviewPortCalls: [],
  };
  const orchestrator = new AgentVariantsOrchestrator({
    getProjectPath: () => (opts.env ?? ENV).projectPath,
    store,
    worktreeManager,
    resolveProjectEnvironment:
      opts.resolveProjectEnvironment ?? (async () => opts.env ?? ENV),
    provisionTimeoutMs: opts.provisionTimeoutMs,
    activeVariantServerIdleTtlMs: opts.activeVariantServerIdleTtlMs,
    devServerRestartDelayMs: opts.devServerRestartDelayMs,
    installDependencies: async (worktreePath: string) => {
      harness.installCalls.push({ worktreePath });
      return harness.installResult;
    },
    previewQaRunner: opts.previewQaRunner ?? passingQaRunner,
    switchPreviewPort: (port) => {
      harness.switchPreviewPortCalls.push(port);
    },
    telemetry: {
      track: (event, properties) =>
        harness.telemetryEvents.push({ event, properties }),
      trackAgentVariantsBriefQuality: (properties) =>
        harness.telemetryEvents.push({
          event: 'agent_variants.brief_quality',
          properties,
        }),
      trackAgentVariantsRequestStarted: (properties) =>
        harness.telemetryEvents.push({
          event: 'agent_variants.request_started',
          properties,
        }),
      trackAgentVariantsRequestAccepted: (properties) =>
        harness.telemetryEvents.push({
          event: 'agent_variants.request_accepted',
          properties,
        }),
      trackAgentVariantsBriefsStarted: (properties) =>
        harness.telemetryEvents.push({
          event: 'agent_variants.briefs_started',
          properties,
        }),
      trackAgentVariantsBriefsCompleted: (properties) =>
        harness.telemetryEvents.push({
          event: 'agent_variants.briefs_completed',
          properties,
        }),
      trackAgentVariantsBriefsFailed: (properties) =>
        harness.telemetryEvents.push({
          event: 'agent_variants.briefs_failed',
          properties,
        }),
      trackAgentVariantsRefinementRequested: (properties) =>
        harness.telemetryEvents.push({
          event: 'agent_variants.refinement_requested',
          properties,
        }),
      trackAgentVariantsRefinementLeased: (properties) =>
        harness.telemetryEvents.push({
          event: 'agent_variants.refinement_leased',
          properties,
        }),
      trackAgentVariantsRefinementCompleted: (properties) =>
        harness.telemetryEvents.push({
          event: 'agent_variants.refinement_completed',
          properties,
        }),
      trackAgentVariantsRefinementFailed: (properties) =>
        harness.telemetryEvents.push({
          event: 'agent_variants.refinement_failed',
          properties,
        }),
      trackAgentVariantsRoundStarted: (properties) =>
        harness.telemetryEvents.push({
          event: 'agent_variants.round_started',
          properties,
        }),
      trackAgentVariantsRoundCompleted: (properties) =>
        harness.telemetryEvents.push({
          event: 'agent_variants.round_completed',
          properties,
        }),
    },
  });
  builtOrchestrators.push(orchestrator);
  return { orchestrator, worktreeManager, store, harness };
}

const builtOrchestrators: AgentVariantsOrchestrator[] = [];

export const briefs = (n: number): Brief[] =>
  Array.from({ length: n }, (_, i) => ({
    briefId: `b${i + 1}`,
    label: `dir ${i + 1}`,
    body: `body ${i + 1}`,
  }));

export async function settleBackgroundWork(): Promise<void> {
  for (let i = 0; i < 6; i++) {
    await new Promise((r) => setTimeout(r, 0));
  }
  await Promise.all(
    builtOrchestrators.map((orchestrator) =>
      orchestrator.settleHistoryPersists(),
    ),
  );
  for (let i = 0; i < 2; i++) {
    await new Promise((r) => setTimeout(r, 0));
  }
}

export const createTempDestination = (): string =>
  path.join(
    os.tmpdir(),
    `rivet-mcp-fresh-${Date.now()}-${Math.random().toString(36).slice(2)}`,
  );

export const readJson = (filePath: string): Record<string, unknown> =>
  JSON.parse(fs.readFileSync(filePath, 'utf8')) as Record<string, unknown>;
